const input = ($input.all()[0] && $input.all()[0].json) || {};
const chatId = input.chat_id;
const comando = input.comando || 'cancelar';
const payload = input.payload || {};
const text = String(input.text || '');

let turnoId = payload.turno_id || '';

if (text.startsWith('cmd:cancelar:turno_id:')) {
  turnoId = text.substring('cmd:cancelar:turno_id:'.length);
} else if (text.startsWith('cancelar:') && text.indexOf(':') === text.lastIndexOf(':')) {
  const candidate = text.substring('cancelar:'.length).trim();
  if (/^\d+$/.test(candidate)) {
    turnoId = candidate;
  }
}

const accion = turnoId ? 'cancelar' : 'pedir_id';

return [{
  json: {
    chat_id: chatId,
    comando: comando,
    accion: accion,
    turno_id: turnoId
  }
}];

// Lee el resultado de PUT /turnos/{id}/cancelar y arma la respuesta.
//
// Tres defectos corregidos acá, todos de la misma familia: el nodo leía del
// item equivocado.
//
// 1. chat_id se leía de $json, pero la respuesta HTTP reemplaza el item y no
//    lo trae -> llegaba undefined y el nodo de Telegram no sabía a dónde
//    enviar. Se lee por nodo nombrado, la regla que documenta el README.
// 2. turno_id se leía de la raíz, pero TurnoResponse expone `id`, no
//    `turno_id` -> el mensaje decía "Turno #undefined cancelado".
// 3. El bloque de errores dependía de input.statusCode, que solo existe con
//    fullResponse: true. Como estaba en false, errorStatus era SIEMPRE falso
//    y el nodo reportaba éxito incluso ante un fallo. Los mensajes de 404 y
//    409 estaban escritos y no podían dispararse nunca.
let chatId = null;
let turnoIdSolicitado = '';
try {
  const decidido = $('Code - Decidir Paso').first().json;
  chatId = decidido.chat_id;
  turnoIdSolicitado = decidido.turno_id || '';
} catch (e) {}

const input = ($input.all()[0] && $input.all()[0].json) || {};
const statusCode = input.statusCode;
const body = input.body || {};
const ok = typeof statusCode === 'number' && statusCode >= 200 && statusCode < 300;

// El id se toma de la respuesta cuando el backend la devuelve; si el turno no
// existe no hay body, y se usa el que pidió el usuario para que el mensaje
// siga diciendo de qué turno habla.
const turnoId = body.id || turnoIdSolicitado;

let mensaje;
if (ok) {
  mensaje = '✅ Turno #' + turnoId + ' cancelado. El horario vuelve a estar disponible.';
} else if (statusCode === 404) {
  mensaje = 'No encontramos el turno #' + turnoId + '. Verificá el número e intentá de nuevo.';
} else if (statusCode === 409) {
  mensaje = 'El turno #' + turnoId + ' ya estaba cancelado, o no se puede cancelar en su estado actual.';
} else {
  const detalle = body.detail ? (' (' + body.detail + ')') : '';
  mensaje = 'No pudimos cancelar el turno' + detalle + '. Intentá de nuevo en un rato.';
}

return [{
  json: {
    chat_id: chatId,
    turno_id: turnoId,
    exito: ok,
    mensaje: mensaje
  }
}];
